$bytes = [Convert]::FromBase64String(($base64 -replace '\s',''))
[System.IO.File]::WriteAllBytes($OutZip, $bytes)

$size = (Get-Item -LiteralPath $OutZip).Length
$hash = (Get-FileHash -LiteralPath $OutZip -Algorithm SHA256).Hash.ToUpper()

Write-Host "WROTE: $OutZip"
Write-Host "SIZE : $size"
Write-Host "SHA  : $hash"

if ($size -ne $ExpectedSize) {
  throw "Size mismatch. Expected $ExpectedSize got $size"
}
if ($hash -ne $ExpectedSha) {
  throw "SHA mismatch. Expected $ExpectedSha got $hash"
}

Write-Host 'OK: x16a.zip rebuilt successfully.' -ForegroundColor Green
